{
  "name": "rf_refresh_cal_cache",
  "confidence": "medium",
  "docstring": "Refreshes a cached RF calibration entry from ROM information, updating packed fields and status/version bytes when changed and initializing defaults when the ROM entry is absent.",
  "subsystem": "rf",
  "var_renames": {
    "a3": "cal_cache",
    "a4": "changed",
    "result": "cal_rom_entry",
    "v7": "rom_status_byte",
    "v8": "rom_field_14",
    "v9": "rom_field_10",
    "v10": "packed_rom_fields_18_22"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "cached RF calibration word 0, packed from ROM entry offset 14"
    },
    {
      "offset": 4,
      "meaning": "cached RF calibration word 1, packed from ROM entry offset 10"
    },
    {
      "offset": 8,
      "meaning": "cached RF calibration word 2, low half packed from ROM entry offset 18"
    },
    {
      "offset": 12,
      "meaning": "cached RF calibration word 3, high half packed from ROM entry offset 22"
    },
    {
      "offset": 16,
      "meaning": "raw cached calibration status byte copied from ROM entry offset 8"
    },
    {
      "offset": 17,
      "meaning": "cached status/flag bits derived from ROM entry fields at offsets 10, 14, 18, and 22"
    },
    {
      "offset": 18,
      "meaning": "cached low-nibble status/version byte used to detect changed calibration entries"
    }
  ]
}
